  if (uMBox == 1 && (u0 < uMBoxR.x - uMBoxE || u0 > uMBoxR.y + uMBoxE || w < uMBoxR.z - uMBoxE || w > uMBoxR.w + uMBoxE)) return vec4(0.0);   // r3: past the map layer's edge: empty (AE reads 0 = black, alpha 0)
